import os
import sys
import fire
import openpyxl

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from _log import log_tool_call


def _read_file(file_path, sheet=None):
    if sheet is None:
        ws = openpyxl.load_workbook(file_path).active
    else:
        ws = openpyxl.load_workbook(file_path)[sheet]
    content = ""
    for row in ws.iter_rows():
        for cell in row:
            value = cell.value if cell.value is not None else "[Empty Cell]"
            content += f"({cell.row}, {cell.column}): {value}\t"
        content += "\n"
    return content


@log_tool_call("excel.read_file")
def main(file_path, sheet=None):
    if not os.path.exists(file_path):
        return f"OBSERVATION: The file {file_path} does not exist. Failed to read the file."
    contents = _read_file(file_path, sheet)
    return f"OBSERVATION: The following is the table from the excel file:\n{contents}"


if __name__ == "__main__":
    fire.Fire(main)

from typing import Any

from tau2.utils import dump_file, get_pydantic_hash, load_file
from tau2.utils.pydantic_utils import BaseModelNoExtra


class DB(BaseModelNoExtra):
    """Domain database.

    This is a base class for all domain databases.
    """

    @classmethod
    def load(cls, path: str) -> "DB":
        """Load the database from a structured file like JSON, YAML, or TOML."""
        data = load_file(path)
        return cls.model_validate(data)

    def dump(self, path: str, exclude_defaults: bool = False, **kwargs: Any) -> None:
        """Dump the database to a file."""
        data = self.model_dump(exclude_defaults=exclude_defaults)
        dump_file(path, data, **kwargs)

    def get_json_schema(self) -> dict[str, Any]:
        """Get the JSON schema of the database."""
        return self.model_json_schema()

    def get_hash(self) -> str:
        """Get the hash of the database."""
        return get_pydantic_hash(self)

    def get_statistics(self) -> dict[str, Any]:
        """Get the statistics of the database."""
        return {}

